/*
 * Finder and Process Manager resources of the classic Mac OS (Retro68)
 * application, compiled by Rez and appended after Retro68's application
 * template, whose SIZE resource the one here replaces.
 *
 * vbam-version.r is generated by CMake (retro68/vbam-version.r.in) and
 * icons.r by make-icons.py.
 */

#include "Processes.r"
#include "Finder.r"

#include "vbam-version.r"
#include "icons.r"

/*
 * The GBA core keeps a cartridge's whole 32 MB address space in memory, so a
 * GBA game needs a partition well above that; Game Boy games fit in the
 * minimum. The Finder's Get Info window can raise either.
 */
resource 'SIZE' (-1) {
    reserved,
    acceptSuspendResumeEvents,
    reserved,
    canBackground,
    doesActivateOnFGSwitch,
    backgroundAndForeground,
    dontGetFrontClicks,
    ignoreChildDiedEvents,
    is32BitCompatible,
    isHighLevelEventAware,
    onlyLocalHLEvents,
    notStationeryAware,
    dontUseTextEditServices,
    reserved,
    reserved,
    reserved,
    64 * 1024 * 1024,
    16 * 1024 * 1024
};

resource 'vers' (1) {
    VBAM_VERS_MAJOR, VBAM_VERS_MINOR, VBAM_VERS_STAGE, VBAM_VERS_PRERELEASE,
    verUS,
    VBAM_VERS_SHORT,
    VBAM_VERS_LONG
};

resource 'vers' (2) {
    VBAM_VERS_MAJOR, VBAM_VERS_MINOR, VBAM_VERS_STAGE, VBAM_VERS_PRERELEASE,
    verUS,
    VBAM_VERS_SHORT,
    "VisualBoyAdvance-M " VBAM_VERS_SHORT
};

/* The owner (signature) resource of the 'VBAM' creator. */
type 'VBAM' as 'STR ';

resource 'VBAM' (0, "Owner resource") {
    "VisualBoyAdvance-M " VBAM_VERS_SHORT
};

/*
 * The application's own icon, and any file at all may be dropped on it: Game
 * Boy and GBA ROMs copied from other systems carry no Mac file type.
 */
resource 'BNDL' (128) {
    'VBAM', 0,
    {
        'ICN#', { 0, 128 };
        'FREF', { 0, 128; 1, 129 }
    }
};

resource 'FREF' (128) { 'APPL', 0, "" };
resource 'FREF' (129) { '****', 0, "" };
